INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(533977, 53843, 327, '<td valign="top">Wow..HayStack. I''m surprised to see it looking so nice and warm [shorts!!!!] after the week of weather we''ve had. The boys in a dark top is a little lost in-front of the dark rock. Other then that this is a nice shot.</td>', 'Wow..HayStack. I''m surprised to see it looking so nice and warm [shorts!!!!] after the week of weather we''ve had. The boys in a dark top is a little lost in-front of the dark rock. Other then that this is a nice shot.', '2004-01-07 00:09:40.000000', NULL, 1),
(533978, 54073, 327, '<td valign="top">Wonderfully creative. I really like this and the shallow dof is super here. Great idea and great shot. Good luck.</td>', 'Wonderfully creative. I really like this and the shallow dof is super here. Great idea and great shot. Good luck.', '2004-01-07 00:10:47.000000', NULL, 1),
(533980, 53459, 7252, '<td valign="top">Very clever</td>', 'Very clever', '2004-01-07 00:13:42.000000', NULL, 1),
(533981, 53766, 327, '<td valign="top">I like this. Like the idea, the light, the focus. I don''t like the blue cloth. Just minor observation. Good luck in the challenge.</td>', 'I like this. Like the idea, the light, the focus. I don''t like the blue cloth. Just minor observation. Good luck in the challenge.', '2004-01-07 00:14:04.000000', NULL, 1),
(533982, 53930, 8816, '<td valign="top">The shot seems out of focus.  If you intended for this, I don''t understand the artistry behind it.  If not, did you use a tripod!?  A nice composition though, and beautiful colors.  Straighten up the horizon though, and use a little neat image to get rid of the noise!</td>', 'The shot seems out of focus.  If you intended for this, I don''t understand the artistry behind it.  If not, did you use a tripod!?  A nice composition though, and beautiful colors.  Straighten up the horizon though, and use a little neat image to get rid of the noise!', '2004-01-07 00:14:22.000000', NULL, 1),
(533986, 53111, 8816, '<td valign="top">wow.  A very brave photo here.  This takes an incredible amount of self-confidence to do.  If you ask me if you can do something like this then you might be happier with who you are then you might think! Bravo to you, for doing this!  Very good composition, a clear message, some slight blur though, and the lighting seems a touch harsh!<br/><br/><i>Message edited by author 2004-01-14 00:14:35.</i></td>', 'wow.  A very brave photo here.  This takes an incredible amount of self-confidence to do.  If you ask me if you can do something like this then you might be happier with who you are then you might think! Bravo to you, for doing this!  Very good composition, a clear message, some slight blur though, and the lighting seems a touch harsh!', '2004-01-07 00:16:38.000000', '2004-01-14 00:14:35.000000', 1),
(533987, 53864, 327, '<td valign="top">Pretty good portrait and I love the idea of keeping warm and safe. I pray that for us all around the world. Your shot: I think the composition could of been a bit better. If she was closer to the center and the tools were cropped out of the shot. Her pose is very good and the lighting is also good. Good luck in the challenge.</td>', 'Pretty good portrait and I love the idea of keeping warm and safe. I pray that for us all around the world. Your shot: I think the composition could of been a bit better. If she was closer to the center and the tools were cropped out of the shot. Her pose is very good and the lighting is also good. Good luck in the challenge.', '2004-01-07 00:16:55.000000', NULL, 1),
(533988, 53985, 11855, '<td valign="top">great concept and expression.... 10 my fav</td>', 'great concept and expression.... 10 my fav', '2004-01-07 00:16:56.000000', NULL, 1),
(533989, 53959, 7252, '<td valign="top">More negative space on both the left and right would to wonders here.</td>', 'More negative space on both the left and right would to wonders here.', '2004-01-07 00:17:37.000000', NULL, 1),
(533990, 53717, 327, '<td valign="top">Very pretty shot. I like the composition and color contrast.</td>', 'Very pretty shot. I like the composition and color contrast.', '2004-01-07 00:17:45.000000', NULL, 1),
(533991, 54077, 8816, '<td valign="top">would be great if you could''ve gotten your black clothes to blend in with the black background, leaving just the skin tones visible in a sea of black!  Without that the image lacks pizazz!  A noble goal, I''m involved with yoga and love it!  Keep it up, it''s fabulous!</td>', 'would be great if you could''ve gotten your black clothes to blend in with the black background, leaving just the skin tones visible in a sea of black!  Without that the image lacks pizazz!  A noble goal, I''m involved with yoga and love it!  Keep it up, it''s fabulous!', '2004-01-07 00:17:55.000000', NULL, 1),
(533993, 53845, 327, '<td valign="top">Really good shot...the lighting is spectacular. Good luck in the challenge.</td>', 'Really good shot...the lighting is spectacular. Good luck in the challenge.', '2004-01-07 00:18:44.000000', NULL, 1),
(533995, 53927, 327, '<td valign="top">Attractive looking group.Maybe they could of been arranged a bit differently? Lighting is nice.</td>', 'Attractive looking group.Maybe they could of been arranged a bit differently? Lighting is nice.', '2004-01-07 00:19:50.000000', NULL, 1),
(533997, 54060, 8816, '<td valign="top">Excellent DOF here!  Nice color, and a nice composition!  It''s IMO bad ettiquette to include something that gives away your identity in a photo though, at least as blatently as in this photo, Mr. Ken Choate.  A nice shot nonetheless!  DOn''t worry I''m not marking you down for that!</td>', 'Excellent DOF here!  Nice color, and a nice composition!  It''s IMO bad ettiquette to include something that gives away your identity in a photo though, at least as blatently as in this photo, Mr. Ken Choate.  A nice shot nonetheless!  DOn''t worry I''m not marking you down for that!', '2004-01-07 00:21:18.000000', NULL, 1),
(534000, 54070, 327, '<td valign="top">lol Good intentions. I think the shot is well done, but on the busy side. Still should do well. Good luck.</td>', 'lol Good intentions. I think the shot is well done, but on the busy side. Still should do well. Good luck.', '2004-01-07 00:28:15.000000', NULL, 1),
