(534592, 53444, 15295, '<td valign="top">A little blurred.  If the focus was sharper I think this would be a great photo.</td>', 'A little blurred.  If the focus was sharper I think this would be a great photo.', '2004-01-07 10:35:07.000000', NULL, 1),
(534593, 53522, 15295, '<td valign="top">Yeah, why stop when you could just ask for something better!</td>', 'Yeah, why stop when you could just ask for something better!', '2004-01-07 10:35:39.000000', NULL, 1),
(534594, 53434, 14448, '<td valign="top">Nice composition, texture, colour and lighting.   I would have prefered a little more depth of field so that the ''5'' wasn''t so soft.  Thematically - maybe it''s me, but I would not have recognized this object as a weight if you hadn''t titled it so.</td>', 'Nice composition, texture, colour and lighting.   I would have prefered a little more depth of field so that the ''5'' wasn''t so soft.  Thematically - maybe it''s me, but I would not have recognized this object as a weight if you hadn''t titled it so.', '2004-01-07 10:36:06.000000', NULL, 1),
(534595, 53497, 15295, '<td valign="top">Great goal, keep on keeping on!</td>', 'Great goal, keep on keeping on!', '2004-01-07 10:36:34.000000', NULL, 1),
(534596, 53357, 15295, '<td valign="top">I really like this shot.  Nice job!</td>', 'I really like this shot.  Nice job!', '2004-01-07 10:37:00.000000', NULL, 1),
(534597, 53853, 13136, '<td valign="top">Good concept. Interesting use of soft instead of sharp lighting. Red smears above left and up arrows are distracting.</td>', 'Good concept. Interesting use of soft instead of sharp lighting. Red smears above left and up arrows are distracting.', '2004-01-07 10:37:07.000000', NULL, 1),
(534598, 53446, 15295, '<td valign="top">This looks like one of them Corona commercials.  Nice!</td>', 'This looks like one of them Corona commercials.  Nice!', '2004-01-07 10:37:46.000000', NULL, 1),
(534599, 53190, 15295, '<td valign="top">Is that a hot dog?</td>', 'Is that a hot dog?', '2004-01-07 10:38:16.000000', NULL, 1),
(534601, 54077, 14620, '<td valign="top">Great soft lighting, nice composition.  Beautiful picture and resolution!</td>', 'Great soft lighting, nice composition.  Beautiful picture and resolution!', '2004-01-07 10:38:35.000000', NULL, 1),
(534602, 53945, 15295, '<td valign="top">Can''t see the flame...</td>', 'Can''t see the flame...', '2004-01-07 10:38:56.000000', NULL, 1),
(534604, 53731, 15295, '<td valign="top">Nice, it looks like an oil painting.</td>', 'Nice, it looks like an oil painting.', '2004-01-07 10:39:23.000000', NULL, 1),
(534605, 53962, 13136, '<td valign="top">Very interesting shot. Are those ice crystals? Good silhouetting. Try to use more of the allowed picture size, I''d like to see this one larger. Good picture.</td>', 'Very interesting shot. Are those ice crystals? Good silhouetting. Try to use more of the allowed picture size, I''d like to see this one larger. Good picture.', '2004-01-07 10:39:51.000000', NULL, 1),
(534606, 53174, 15295, '<td valign="top">It would''ve been cooler if this was actually outdoors.  Nice shot none the less.</td>', 'It would''ve been cooler if this was actually outdoors.  Nice shot none the less.', '2004-01-07 10:40:03.000000', NULL, 1),
(534607, 53664, 15295, '<td valign="top">You know!</td>', 'You know!', '2004-01-07 10:40:18.000000', NULL, 1),
(534608, 53845, 15295, '<td valign="top">Nice shot!</td>', 'Nice shot!', '2004-01-07 10:40:57.000000', NULL, 1),
(534610, 53717, 15295, '<td valign="top">Nice</td>', 'Nice', '2004-01-07 10:41:55.000000', NULL, 1),
(534611, 53522, 8139, '<td valign="top">Nonconformist, hey.<br/>Good setup and colors.<br/>The ash tree is somewhat too overburned</td>', 'Nonconformist, hey.Good setup and colors.The ash tree is somewhat too overburned', '2004-01-07 10:41:57.000000', NULL, 1),
(534616, 53880, 13136, '<td valign="top">Did you really want the arms in the left top of your picture? Cute little girl. Nice location and pose.</td>', 'Did you really want the arms in the left top of your picture? Cute little girl. Nice location and pose.', '2004-01-07 10:43:39.000000', NULL, 1),
(534617, 53856, 15295, '<td valign="top">Barefoot would''ve been better.</td>', 'Barefoot would''ve been better.', '2004-01-07 10:43:50.000000', NULL, 1),
(534618, 54074, 15295, '<td valign="top">I like the smoke in this picture.</td>', 'I like the smoke in this picture.', '2004-01-07 10:44:05.000000', NULL, 1),
(534621, 53946, 14448, '<td valign="top">I like the composition and colouring.  The shadows under fingers are distracting.  Biggest problem for me is depth of field: only the palm appears in focus, and everything else including the subject is out of focus.  Thematic fit.</td>', 'I like the composition and colouring.  The shadows under fingers are distracting.  Biggest problem for me is depth of field: only the palm appears in focus, and everything else including the subject is out of focus.  Thematic fit.', '2004-01-07 10:45:55.000000', NULL, 1),
(534624, 53111, 15295, '<td valign="top">Shadows and the B&amp;W are nice choices for this photograph.  Just taking this photo I think you are on your way to achieving your resolution.  Good job.</td>', 'Shadows and the B&W are nice choices for this photograph.  Just taking this photo I think you are on your way to achieving your resolution.  Good job.', '2004-01-07 10:47:24.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(534626, 53114, 13136, '<td valign="top">OWWWW! My eyes hurt. I feel like I''m falling. What is "sibr"? New Year''s Monitor Resolution?</td>', 'OWWWW! My eyes hurt. I feel like I''m falling. What is "sibr"? New Year''s Monitor Resolution?', '2004-01-07 10:47:54.000000', NULL, 1),
(534627, 53981, 13136, '<td valign="top">Start by cleaning the lint off the lense. Ha Ha. Nice shot of a great camera. Don''t know if this is an improvement, but it''s good now.</td>', 'Start by cleaning the lint off the lense. Ha Ha. Nice shot of a great camera. Don''t know if this is an improvement, but it''s good now.', '2004-01-07 10:49:05.000000', NULL, 1),
(534630, 54020, 13136, '<td valign="top">Made me laugh. Nice portrait. This one goes on next year''s Christmas Cards, right?</td>', 'Made me laugh. Nice portrait. This one goes on next year''s Christmas Cards, right?', '2004-01-07 10:50:54.000000', NULL, 1),
(534633, 53165, 14448, '<td valign="top">Very good technically and artistically.  I like the play of the brightly lit small branches against the dark blue sky.  The only distracting blemishes I can see are the two shadows on the branch in the bottom left corner (easy to fix later).  Very good expression of the theme.  Well done.</td>', 'Very good technically and artistically.  I like the play of the brightly lit small branches against the dark blue sky.  The only distracting blemishes I can see are the two shadows on the branch in the bottom left corner (easy to fix later).  Very good expression of the theme.  Well done.', '2004-01-07 10:53:44.000000', NULL, 1),
(534637, 53846, 15295, '<td valign="top">This is funny.</td>', 'This is funny.', '2004-01-07 10:57:54.000000', NULL, 1),
(534638, 53985, 15295, '<td valign="top">I like the shadows!</td>', 'I like the shadows!', '2004-01-07 10:58:14.000000', NULL, 1),
(534639, 53459, 15295, '<td valign="top">Nice shot, very nice shot.</td>', 'Nice shot, very nice shot.', '2004-01-07 10:58:38.000000', NULL, 1),
(534640, 54091, 15295, '<td valign="top">maybe</td>', 'maybe', '2004-01-07 10:58:52.000000', NULL, 1),
(534641, 53886, 3102, '<td valign="top">Dang -- it hurts just looking at this!</td>', 'Dang -- it hurts just looking at this!', '2004-01-07 10:58:59.000000', NULL, 1),
(534643, 53525, 15295, '<td valign="top">Nice, how did you get this shot?</td>', 'Nice, how did you get this shot?', '2004-01-07 10:59:27.000000', NULL, 1),
(534644, 54075, 14448, '<td valign="top">Nice crib!  If that''s a deck attached in the centre, it''s quite hard to distinguish due to the distance.  Much of subject is quite dark - rebalancing brightness and contrast might help.</td>', 'Nice crib!  If that''s a deck attached in the centre, it''s quite hard to distinguish due to the distance.  Much of subject is quite dark - rebalancing brightness and contrast might help.', '2004-01-07 10:59:43.000000', NULL, 1),
(534645, 53146, 15295, '<td valign="top">Come on pimp!</td>', 'Come on pimp!', '2004-01-07 11:00:05.000000', NULL, 1),
(534648, 53490, 15295, '<td valign="top">I really like the reflections.</td>', 'I really like the reflections.', '2004-01-07 11:00:53.000000', NULL, 1),
(534649, 53932, 15295, '<td valign="top">Great sunset.</td>', 'Great sunset.', '2004-01-07 11:01:04.000000', NULL, 1),
(534651, 53254, 15295, '<td valign="top">I like the eye glass shot.  Great job!</td>', 'I like the eye glass shot.  Great job!', '2004-01-07 11:01:58.000000', NULL, 1),
(534655, 53150, 15295, '<td valign="top">Maybe a black backdrop would make this picture better.</td>', 'Maybe a black backdrop would make this picture better.', '2004-01-07 11:02:24.000000', NULL, 1),
(534656, 53904, 3102, '<td valign="top">Lord of the Rings?</td>', 'Lord of the Rings?', '2004-01-07 11:02:49.000000', NULL, 1),
(534657, 54028, 15295, '<td valign="top">Awe man this is nice...</td>', 'Awe man this is nice...', '2004-01-07 11:03:00.000000', NULL, 1),
(534658, 54032, 3102, '<td valign="top">Beautiful colors!</td>', 'Beautiful colors!', '2004-01-07 11:03:16.000000', NULL, 1),
(534664, 53788, 3102, '<td valign="top">Mmmmm... mmmmm!  I''d last about an hour on this diet :)</td>', 'Mmmmm... mmmmm!  I''d last about an hour on this diet :)', '2004-01-07 11:05:36.000000', NULL, 1),
(534671, 53863, 3102, '<td valign="top">How is that a New Year''s resolution...?</td>', 'How is that a New Year''s resolution...?', '2004-01-07 11:09:26.000000', NULL, 1),
(534674, 53679, 14448, '<td valign="top">I like this.  Great expression of the theme.  Good composition and contasts.  Would have preferred subject closer and more framed by trees.  Image a little grainy.  I find the heavy vignetting distracting. 7</td>', 'I like this.  Great expression of the theme.  Good composition and contasts.  Would have preferred subject closer and more framed by trees.  Image a little grainy.  I find the heavy vignetting distracting. 7', '2004-01-07 11:15:29.000000', NULL, 1),
(534675, 54060, 3102, '<td valign="top">Looks like the work of kernalklik to me!  (There are a couple clues here, I guess.)</td>', 'Looks like the work of kernalklik to me!  (There are a couple clues here, I guess.)', '2004-01-07 11:15:31.000000', NULL, 1),
(534678, 54096, 11321, '<td valign="top">good luck :)</td>', 'good luck :)', '2004-01-07 11:17:14.000000', NULL, 1),
(534680, 53114, 14448, '<td valign="top">Sorry, I don''t get fit to theme.  Don''t know what ''sibr'' is.  Focus and sharpness lacking.  Distracting moire patterns.</td>', 'Sorry, I don''t get fit to theme.  Don''t know what ''sibr'' is.  Focus and sharpness lacking.  Distracting moire patterns.', '2004-01-07 11:22:08.000000', NULL, 1),
(534683, 53506, 14448, '<td valign="top">Funny!  Nice idea and expression.  Filtering needed, as the artificial lighting made all the ice creams unnaturally yellow.</td>', 'Funny!  Nice idea and expression.  Filtering needed, as the artificial lighting made all the ice creams unnaturally yellow.', '2004-01-07 11:24:22.000000', NULL, 1),
(534685, 53145, 13822, '<td valign="top">Flott</td>', 'Flott', '2004-01-07 11:26:06.000000', NULL, 1),
(534692, 53362, 10047, '<td valign="top">My computer desk looks about the same. Many of the straight edges seem to have jaggies.</td>', 'My computer desk looks about the same. Many of the straight edges seem to have jaggies.', '2004-01-07 11:35:51.000000', NULL, 1),
(534693, 53945, 10047, '<td valign="top">I think the photo needs to be darkened or less bright.</td>', 'I think the photo needs to be darkened or less bright.', '2004-01-07 11:36:58.000000', NULL, 1),
(534694, 53906, 10047, '<td valign="top">Looks like the jagged edges showed up when you reduced the size of the photo.</td>', 'Looks like the jagged edges showed up when you reduced the size of the photo.', '2004-01-07 11:38:25.000000', NULL, 1),
(534695, 53968, 14453, '<td valign="top">Good courage!</td>', 'Good courage!', '2004-01-07 11:38:32.000000', NULL, 1),
(534696, 54099, 13759, '<td valign="top">How cute! It´s a beautiful baby. The clothes are perfectly exposed, but the face is not so well. It may be happened by the use of a spot meter that creates a little confusion abaut exposure. The baby´s face correctly exposed will bring more value to this photo.</td>', 'How cute! It´s a beautiful baby. The clothes are perfectly exposed, but the face is not so well. It may be happened by the use of a spot meter that creates a little confusion abaut exposure. The baby´s face correctly exposed will bring more value to this photo.', '2004-01-07 11:38:53.000000', NULL, 1),
(534699, 53274, 10047, '<td valign="top">I''m not sure what the New Years Resolution is. Not sure if there is some post processing you could to make the rapto stand out more.</td>', 'I''m not sure what the New Years Resolution is. Not sure if there is some post processing you could to make the rapto stand out more.', '2004-01-07 11:40:27.000000', NULL, 1),
(534700, 54032, 13759, '<td valign="top">Wow, how nice and powerful image you had taken!  You do a great job with this exposition, capturing the sky details and rail details perfectly. Congratulations. It´s very impressive.</td>', 'Wow, how nice and powerful image you had taken!  You do a great job with this exposition, capturing the sky details and rail details perfectly. Congratulations. It´s very impressive.', '2004-01-07 11:42:15.000000', NULL, 1),
(534701, 54074, 10047, '<td valign="top">Nice effect. Good luck with breaking the habit. After the challenge I''d like to know how you set up the photo. I haven''t had very good luck with capturing smoke.</td>', 'Nice effect. Good luck with breaking the habit. After the challenge I''d like to know how you set up the photo. I haven''t had very good luck with capturing smoke.', '2004-01-07 11:43:00.000000', NULL, 1),
(534702, 53525, 10047, '<td valign="top">My favorite for this challenge. Exceptional clarity and detail. Nice colors also.</td>', 'My favorite for this challenge. Exceptional clarity and detail. Nice colors also.', '2004-01-07 11:45:11.000000', NULL, 1),
(534705, 54048, 13759, '<td valign="top">If you setup your light a little higher and control your exposure to the face it will be a good portrait. The shoulder and a piece of wall has the full focus and correct exposure at this moment.</td>', 'If you setup your light a little higher and control your exposure to the face it will be a good portrait. The shoulder and a piece of wall has the full focus and correct exposure at this moment.', '2004-01-07 11:46:16.000000', NULL, 1),
(534706, 53717, 10047, '<td valign="top">Beautiful capture. Its always a great feeling when you can spot the simple yet beautiful things, especially if you have walked past them many times before without noticing.</td>', 'Beautiful capture. Its always a great feeling when you can spot the simple yet beautiful things, especially if you have walked past them many times before without noticing.', '2004-01-07 11:47:12.000000', NULL, 1),
(534708, 53274, 10799, '<td valign="top">What is your resolution....?  I can''t tell from the title and photo?  I think the photo needs a bit more contrast.</td>', 'What is your resolution....?  I can''t tell from the title and photo?  I think the photo needs a bit more contrast.', '2004-01-07 11:49:01.000000', NULL, 1),
(534709, 53927, 13759, '<td valign="top">Good shot. A little bounced flash will help a lot to give more details of the poeple. If you can´t do it, because can´t bouce your flash, bring the light more closer to you can help too.</td>', 'Good shot. A little bounced flash will help a lot to give more details of the poeple. If you can´t do it, because can´t bouce your flash, bring the light more closer to you can help too.', '2004-01-07 11:49:57.000000', NULL, 1),
(534713, 54032, 10799, '<td valign="top">I love this shot!  It has great depth.</td>', 'I love this shot!  It has great depth.', '2004-01-07 11:53:53.000000', NULL, 1),
(534714, 53362, 13759, '<td valign="top">Ho, ho...  you will had distration to all the year! Great idea. The BW look put the things all in the same place. Not is distracting me, cause this. The contrasts, in this shot may be adjusted to give more details setting the white/black point and a bit of curves adjustment.</td>', 'Ho, ho...  you will had distration to all the year! Great idea. The BW look put the things all in the same place. Not is distracting me, cause this. The contrasts, in this shot may be adjusted to give more details setting the white/black point and a bit of curves adjustment.', '2004-01-07 11:54:21.000000', NULL, 1),
(534716, 53518, 10799, '<td valign="top">What is your resolution?  I can not tell from the title or the photo.  Great photo.</td>', 'What is your resolution?  I can not tell from the title or the photo.  Great photo.', '2004-01-07 11:57:01.000000', NULL, 1),
(534717, 54032, 10047, '<td valign="top">Beautiful shot. Nice earth tone colors. The light on the horizon really seems to draw me right down the tracks.</td>', 'Beautiful shot. Nice earth tone colors. The light on the horizon really seems to draw me right down the tracks.', '2004-01-07 11:57:21.000000', NULL, 1),
(534718, 53522, 14448, '<td valign="top">Nice colours and composition.  Whiteness of ash tray, and whatever is visible through its slot, are distracting.  I can provide scotch recommendations!</td>', 'Nice colours and composition.  Whiteness of ash tray, and whatever is visible through its slot, are distracting.  I can provide scotch recommendations!', '2004-01-07 11:57:43.000000', NULL, 1),
(534719, 53856, 13759, '<td valign="top">NIce idea. Good Shot. The feet are a bit underexposed, due to the bright skys. The looking of the scene itself may be improved with the &lt;a href=''//www.dpchallenge.com/tutorial.php?TUTORIAL_ID=5''&gt;Rule of Thirds&lt;/a&gt;.</td>', 'NIce idea. Good Shot. The feet are a bit underexposed, due to the bright skys. The looking of the scene itself may be improved with the <a href=''//www.dpchallenge.com/tutorial.php?TUTORIAL_ID=5''>Rule of Thirds</a>.', '2004-01-07 11:57:53.000000', NULL, 1),
(534720, 53874, 10047, '<td valign="top">Great capture! Nice spectrum of colors.</td>', 'Great capture! Nice spectrum of colors.', '2004-01-07 11:58:14.000000', NULL, 1),
(534721, 53687, 10047, '<td valign="top">Nice composition. I like how the light plays off the highpoints.</td>', 'Nice composition. I like how the light plays off the highpoints.', '2004-01-07 12:00:07.000000', NULL, 1),
(534722, 54078, 14448, '<td valign="top">Good composition.  I like choice of B&amp;W.  No technical problems.  Good expression of theme.</td>', 'Good composition.  I like choice of B&W.  No technical problems.  Good expression of theme.', '2004-01-07 12:00:24.000000', NULL, 1),
(534723, 54085, 10047, '<td valign="top">Nice composition and a pretty model. Nice contrast of colors forming the natural framing.</td>', 'Nice composition and a pretty model. Nice contrast of colors forming the natural framing.', '2004-01-07 12:01:31.000000', NULL, 1),
(534725, 54060, 13759, '<td valign="top">I like so much of it. The way DOF was used creating the background was special. The only mistake is to put your real name in this card. Now we can know the photographer, and it can be bad to your votings. Great job.</td>', 'I like so much of it. The way DOF was used creating the background was special. The only mistake is to put your real name in this card. Now we can know the photographer, and it can be bad to your votings. Great job.', '2004-01-07 12:02:34.000000', NULL, 1),
(534732, 54032, 13136, '<td valign="top">I like this shot. I tend to like high contrast shots and you got that here. You also managed to keep things close (plant at bottom) in focus as well as things far away. Nice shot.</td>', 'I like this shot. I tend to like high contrast shots and you got that here. You also managed to keep things close (plant at bottom) in focus as well as things far away. Nice shot.', '2004-01-07 12:08:30.000000', NULL, 1),
(534733, 53730, 11241, '<td valign="top">Love the detail in this shot....and the DOF is great to...10</td>', 'Love the detail in this shot....and the DOF is great to...10', '2004-01-07 12:09:33.000000', NULL, 1),
(534734, 54072, 327, '<td valign="top">I like your idea. I do think the crop could of been tighter to remove the carpet/background. You want the swimsuit, the girl or her figure? LOL Good luck in the challenge.</td>', 'I like your idea. I do think the crop could of been tighter to remove the carpet/background. You want the swimsuit, the girl or her figure? LOL Good luck in the challenge.', '2004-01-07 12:09:59.000000', NULL, 1),
(534736, 53899, 327, '<td valign="top">Pretty moth or butterfly. I might of tried to focus on the wings a bit more and not so much on the cocoon. The colors are really nice as is the lighting.</td>', 'Pretty moth or butterfly. I might of tried to focus on the wings a bit more and not so much on the cocoon. The colors are really nice as is the lighting.', '2004-01-07 12:11:28.000000', NULL, 1),
(534737, 53843, 13759, '<td valign="top">I like so much from the landscape, despite of the horizon that is incorrect, but... What that runner is doing there? Read the rule of thirds in this site tutorials section, it will help you to improve the message about the subject of a photography.</td>', 'I like so much from the landscape, despite of the horizon that is incorrect, but... What that runner is doing there? Read the rule of thirds in this site tutorials section, it will help you to improve the message about the subject of a photography.', '2004-01-07 12:12:10.000000', NULL, 1),
(534739, 53072, 327, '<td valign="top">Clear shot, good focus. I don''t find it very interesting to look at. Maybe  it''s the b&amp;w or just the composition. Still  your shot is good.</td>', 'Clear shot, good focus. I don''t find it very interesting to look at. Maybe  it''s the b&w or just the composition. Still  your shot is good.', '2004-01-07 12:12:24.000000', NULL, 1),
(534740, 53982, 13136, '<td valign="top">The footsteps look raised. I have to really think about it to see that they are indented. Cool effect. Good shot.</td>', 'The footsteps look raised. I have to really think about it to see that they are indented. Cool effect. Good shot.', '2004-01-07 12:12:51.000000', NULL, 1),
(534743, 53965, 327, '<td valign="top">Pretty shot, pretty leg. Really looks inviting. Maybe a some more diffusing of the light would of prevented the glare on the tub? Over all it''s very nice and good thought for the new year.</td>', 'Pretty shot, pretty leg. Really looks inviting. Maybe a some more diffusing of the light would of prevented the glare on the tub? Over all it''s very nice and good thought for the new year.', '2004-01-07 12:13:57.000000', NULL, 1),
(534744, 53525, 13136, '<td valign="top">Great close-up. Wonderful color, lighting and framing. Should do well.</td>', 'Great close-up. Wonderful color, lighting and framing. Should do well.', '2004-01-07 12:14:25.000000', NULL, 1),
(534745, 53988, 327, '<td valign="top">I like this idea and I like the subject composition. The tones are also pleasing. Maybe a bit more focus.</td>', 'I like this idea and I like the subject composition. The tones are also pleasing. Maybe a bit more focus.', '2004-01-07 12:14:41.000000', NULL, 1),
(534746, 53856, 327, '<td valign="top">I like this idea, but think the feet fall short. The shocks are not interesting, maybe some red shocks? &lt;or&gt; some stripes would of given this a bit more punch.</td>', 'I like this idea, but think the feet fall short. The shocks are not interesting, maybe some red shocks? <or> some stripes would of given this a bit more punch.', '2004-01-07 12:15:44.000000', NULL, 1),
(534747, 54079, 13136, '<td valign="top">Cute idea. Nice execution. Works well with sepia.</td>', 'Cute idea. Nice execution. Works well with sepia.', '2004-01-07 12:16:21.000000', NULL, 1),
(534748, 53488, 327, '<td valign="top">Very nice focus and composition. Of course the subject is nasty and may turn some viewers away. No matter I like this. Good photo.</td>', 'Very nice focus and composition. Of course the subject is nasty and may turn some viewers away. No matter I like this. Good photo.', '2004-01-07 12:16:33.000000', NULL, 1),
(534749, 53905, 13759, '<td valign="top">Start to trying on a hard surface like a street or sidewalk! The green is so smooth and the wheels hangs on it.</td>', 'Start to trying on a hard surface like a street or sidewalk! The green is so smooth and the wheels hangs on it.', '2004-01-07 12:16:40.000000', NULL, 1),
(534751, 54077, 13136, '<td valign="top">Nice soft focus. I like how the outfit blends with the background.</td>', 'Nice soft focus. I like how the outfit blends with the background.', '2004-01-07 12:17:34.000000', NULL, 1),
