(535394, 53872, 15242, '<td valign="top">This shot isn''t very interesting and the lighting isn''t very good.</td>', 'This shot isn''t very interesting and the lighting isn''t very good.', '2004-01-07 18:51:51.000000', NULL, 1),
(535395, 53165, 5822, '<td valign="top">Great message, and even inspirational! I like the colors but wish the sky was more even toned.</td>', 'Great message, and even inspirational! I like the colors but wish the sky was more even toned.', '2004-01-07 18:52:08.000000', NULL, 1),
(535397, 53983, 15242, '<td valign="top">The lighting is good, but a flat (non-shiny) and smooth background would make this so much better.</td>', 'The lighting is good, but a flat (non-shiny) and smooth background would make this so much better.', '2004-01-07 18:54:03.000000', NULL, 1),
(535398, 53190, 5822, '<td valign="top">Great DOF and focus on your subjects. I really like the way most of the color in the shot resides with the woman. And most of all, I like your message! Well done.</td>', 'Great DOF and focus on your subjects. I really like the way most of the color in the shot resides with the woman. And most of all, I like your message! Well done.', '2004-01-07 18:55:08.000000', NULL, 1),
(535403, 53962, 15242, '<td valign="top">Great shot.  I can never take a good photo with the sun in it.  Maybe crop a little more off the top and bottom.</td>', 'Great shot.  I can never take a good photo with the sun in it.  Maybe crop a little more off the top and bottom.', '2004-01-07 18:56:19.000000', NULL, 1),
(535405, 54046, 15242, '<td valign="top">Black and white captures the moment  perfectly!</td>', 'Black and white captures the moment  perfectly!', '2004-01-07 18:57:20.000000', NULL, 1),
(535406, 54079, 5822, '<td valign="top">What pockets! A little harsh on the glare, but overall, I like the compostion and tones alot.</td>', 'What pockets! A little harsh on the glare, but overall, I like the compostion and tones alot.', '2004-01-07 18:57:40.000000', NULL, 1),
(535408, 53932, 15242, '<td valign="top">Not sure about the title or how it fits the challenge, but I''ll forget about that.  Beautiful catch!</td>', 'Not sure about the title or how it fits the challenge, but I''ll forget about that.  Beautiful catch!', '2004-01-07 18:58:51.000000', NULL, 1),
