(535419, 54102, 15242, '<td valign="top">Calculus!  My favorite!</td>', 'Calculus!  My favorite!', '2004-01-07 19:04:59.000000', NULL, 1),
(535420, 53930, 5822, '<td valign="top">Very nice compostion in this serene shot. I especially like the silouetted boat and setting sun against the clouds. Very classic shot that you captured well. I think it could be improved by getting rid of the noise in the shot, but overall, I like. Just not sure how this relates to the challenge theme.</td>', 'Very nice compostion in this serene shot. I especially like the silouetted boat and setting sun against the clouds. Very classic shot that you captured well. I think it could be improved by getting rid of the noise in the shot, but overall, I like. Just not sure how this relates to the challenge theme.', '2004-01-07 19:06:39.000000', NULL, 1),
(535421, 53687, 15242, '<td valign="top">Shine that puppy up a little better and be sure not to catch all sorts of other stuff in the room in the reflection next time.  Good idea though.</td>', 'Shine that puppy up a little better and be sure not to catch all sorts of other stuff in the room in the reflection next time.  Good idea though.', '2004-01-07 19:06:50.000000', NULL, 1),
(535422, 53440, 15029, '<td valign="top">It looks like you photoshoped the background. next time, try to do a neater job. You left too many white specks and lines.</td>', 'It looks like you photoshoped the background. next time, try to do a neater job. You left too many white specks and lines.', '2004-01-07 19:07:19.000000', NULL, 1),
(535423, 53872, 15029, '<td valign="top">slightly overexposed. making the shot darker will probably better convey the feeling of cold.</td>', 'slightly overexposed. making the shot darker will probably better convey the feeling of cold.', '2004-01-07 19:08:06.000000', NULL, 1),
(535424, 53940, 5822, '<td valign="top">Hey, this is great! I love this kind of dark and moody shot!  Really gives you a feel of cold winter.  Only thing I think it may be missing is the moon, but then again, that would be stock...well done and good luck.</td>', 'Hey, this is great! I love this kind of dark and moody shot!  Really gives you a feel of cold winter.  Only thing I think it may be missing is the moon, but then again, that would be stock...well done and good luck.', '2004-01-07 19:08:51.000000', NULL, 1),
(535425, 53274, 15242, '<td valign="top">The sky is too bright, everything seems out of focus, and you should have waited for it to lift it''s head.</td>', 'The sky is too bright, everything seems out of focus, and you should have waited for it to lift it''s head.', '2004-01-07 19:09:06.000000', NULL, 1),
