(536997, 54078, 5822, '<td valign="top">Tones and lighting are very good here, but image has some noise problems. I like the composition as well, but probably would have looked better in color.</td>', 'Tones and lighting are very good here, but image has some noise problems. I like the composition as well, but probably would have looked better in color.', '2004-01-08 23:41:39.000000', NULL, 1),
(537009, 54086, 5822, '<td valign="top">Composition shows firm resolve and attitude! I like how you portray that with some hand movement. Fingers are too dirty looking (noise?).</td>', 'Composition shows firm resolve and attitude! I like how you portray that with some hand movement. Fingers are too dirty looking (noise?).', '2004-01-08 23:50:07.000000', NULL, 1),
(537013, 53150, 5822, '<td valign="top">Mannequins are posed very well. They have character. Background makes it look like they are on stage, but the yellow could have been eliminated and I don''t like the green tablecloth.  Lighting is a bit strong, but there are no glaring areas, so this is not really a problem.  Finally, the table line is slanted and needs some rotation.</td>', 'Mannequins are posed very well. They have character. Background makes it look like they are on stage, but the yellow could have been eliminated and I don''t like the green tablecloth.  Lighting is a bit strong, but there are no glaring areas, so this is not really a problem.  Finally, the table line is slanted and needs some rotation.', '2004-01-08 23:57:42.000000', NULL, 1),
(537015, 53966, 5822, '<td valign="top">Uninspiring composition.</td>', 'Uninspiring composition.', '2004-01-08 23:59:34.000000', NULL, 1),
