(537285, 54085, 12733, '<td valign="top">Nice compostion, great lighting and an attractive model. Adds up to a very nice picture.</td>', 'Nice compostion, great lighting and an attractive model. Adds up to a very nice picture.', '2004-01-09 11:20:54.000000', NULL, 1),
(537287, 53966, 12733, '<td valign="top">The leftover pizza is kind of a turnoff, and the lighting is kind of flat and dim.</td>', 'The leftover pizza is kind of a turnoff, and the lighting is kind of flat and dim.', '2004-01-09 11:22:05.000000', NULL, 1),
