(540242, 54027, 6405, '<td valign="top">Don''t understand the message here !</td>', 'Don''t understand the message here !', '2004-01-12 20:11:09.000000', NULL, 1),
(540317, 53165, 15834, '<td valign="top">Great view. I like the contrast of the sky vs. the trees. Nice!</td>', 'Great view. I like the contrast of the sky vs. the trees. Nice!', '2004-01-12 21:02:10.000000', NULL, 1),
(540322, 53440, 15834, '<td valign="top">This is interesting and beautiful. I think the center is dominated with a little too much white, but it''s still a great photo.</td>', 'This is interesting and beautiful. I think the center is dominated with a little too much white, but it''s still a great photo.', '2004-01-12 21:06:09.000000', NULL, 1),
(540323, 53174, 15834, '<td valign="top">The flower contrasts nicely against the background. However I think it could have been much better without the glass behind it distorting the background. The glass picks up the flash and it also has condensation on it. But I think it''s a nice image.</td>', 'The flower contrasts nicely against the background. However I think it could have been much better without the glass behind it distorting the background. The glass picks up the flash and it also has condensation on it. But I think it''s a nice image.', '2004-01-12 21:09:34.000000', NULL, 1),
(540330, 53429, 7252, '<td valign="top">I''ve come back to this photo a half dozen times and I am no closer now than I was the first time I looked at it to determining what New Year''s resolution you might be displaying here. I anxiously look forward to seeing if there are any photographer''s comments when the challenge is over.</td>', 'I''ve come back to this photo a half dozen times and I am no closer now than I was the first time I looked at it to determining what New Year''s resolution you might be displaying here. I anxiously look forward to seeing if there are any photographer''s comments when the challenge is over.', '2004-01-12 21:21:40.000000', NULL, 1),
(540351, 54027, 12151, '<td valign="top">This is a nice angle of the shot, and you''ve coupled it nicely with the motion blurs framing the subject.  I think even more motion blur in this case would be more appealing to me.</td>', 'This is a nice angle of the shot, and you''ve coupled it nicely with the motion blurs framing the subject.  I think even more motion blur in this case would be more appealing to me.', '2004-01-12 21:38:14.000000', NULL, 1),
(540354, 53165, 12151, '<td valign="top">In this case, I would want this photo even clearer, so that even those thin branches aren''t blurred.  Otherwise, this is a stunning photograph in terms of both shape and color.  (It should be in a mathematics textbook on fractals.)</td>', 'In this case, I would want this photo even clearer, so that even those thin branches aren''t blurred.  Otherwise, this is a stunning photograph in terms of both shape and color.  (It should be in a mathematics textbook on fractals.)', '2004-01-12 21:40:46.000000', NULL, 1),
(540361, 53273, 12151, '<td valign="top">Beautiful exhibition of variable depth of focus.  The soft green is extremely inviting.</td>', 'Beautiful exhibition of variable depth of focus.  The soft green is extremely inviting.', '2004-01-12 21:42:23.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(540365, 52999, 12151, '<td valign="top">Somehow, this is a hilarious photo.  And it looks really nice, too - the golden lighting on the fatted squirrel is great.  The linear background is in excellent juxtaposition with the furry animal too.  Nice job.  Despite, the fact that I''m unsure how it relates to the theme, it takes my top vote for the week...</td>', 'Somehow, this is a hilarious photo.  And it looks really nice, too - the golden lighting on the fatted squirrel is great.  The linear background is in excellent juxtaposition with the furry animal too.  Nice job.  Despite, the fact that I''m unsure how it relates to the theme, it takes my top vote for the week...', '2004-01-12 21:43:02.000000', NULL, 1),
(540392, 54032, 14496, '<td valign="top">Very original.  Great color of the rails - very vibrent.  Nice shot!</td>', 'Very original.  Great color of the rails - very vibrent.  Nice shot!', '2004-01-12 21:58:05.000000', NULL, 1),
(540397, 54073, 14496, '<td valign="top">I was looking for original submissions for this challenge and I think this fits the bill!  Very creative and a good resolution too!</td>', 'I was looking for original submissions for this challenge and I think this fits the bill!  Very creative and a good resolution too!', '2004-01-12 22:00:08.000000', NULL, 1),
(540399, 53921, 14496, '<td valign="top">Very funny title.  Looks a little blurry though.</td>', 'Very funny title.  Looks a little blurry though.', '2004-01-12 22:00:54.000000', NULL, 1),
(540401, 54067, 14496, '<td valign="top">I can''t tell it''s a school  building without the title of the photo.  It could be anything.</td>', 'I can''t tell it''s a school  building without the title of the photo.  It could be anything.', '2004-01-12 22:01:46.000000', NULL, 1),
(540404, 53687, 14496, '<td valign="top">I  like the idea of light reflecting off the sax, but I don''t like what''s reflected here. I think it may be better if I wasn''t seeing the room or the red-ish light.  I like the angle of the photo though.</td>', 'I  like the idea of light reflecting off the sax, but I don''t like what''s reflected here. I think it may be better if I wasn''t seeing the room or the red-ish light.  I like the angle of the photo though.', '2004-01-12 22:03:13.000000', NULL, 1),
(540405, 54027, 14496, '<td valign="top">I don''t get it.</td>', 'I don''t get it.', '2004-01-12 22:03:29.000000', NULL, 1),
(540410, 53114, 14496, '<td valign="top">I don''t know what sibr is. I know it''s a computer screen, but it looks too blury.</td>', 'I don''t know what sibr is. I know it''s a computer screen, but it looks too blury.', '2004-01-12 22:04:37.000000', NULL, 1),
(540411, 53845, 14496, '<td valign="top">Very nice.  I like the composition and the softness of the photo.</td>', 'Very nice.  I like the composition and the softness of the photo.', '2004-01-12 22:05:07.000000', NULL, 1),
(540413, 54075, 14496, '<td valign="top">Very funny title.  Wish I lived there!  I like the lighting and the sky.</td>', 'Very funny title.  Wish I lived there!  I like the lighting and the sky.', '2004-01-12 22:06:25.000000', NULL, 1),
(540415, 53874, 14496, '<td valign="top">Although it''s a pretty sunset, it looks almost ominous.  Nice capture!</td>', 'Although it''s a pretty sunset, it looks almost ominous.  Nice capture!', '2004-01-12 22:07:22.000000', NULL, 1),
(540416, 53945, 14496, '<td valign="top">I can''t tell it''s a candle.</td>', 'I can''t tell it''s a candle.', '2004-01-12 22:07:50.000000', NULL, 1),
(540417, 53111, 14496, '<td valign="top">Very nice.  Original and I like the angle.</td>', 'Very nice.  Original and I like the angle.', '2004-01-12 22:08:11.000000', NULL, 1),
(540420, 53031, 14496, '<td valign="top">Similar to the photo about higher education, I can''t tell it''s a library without the title and I think that needs to be apparent.</td>', 'Similar to the photo about higher education, I can''t tell it''s a library without the title and I think that needs to be apparent.', '2004-01-12 22:08:58.000000', NULL, 1),
(540423, 53357, 14496, '<td valign="top">Very nice compsition. I like the angle of the balls with the cue and the blue felt is great.</td>', 'Very nice compsition. I like the angle of the balls with the cue and the blue felt is great.', '2004-01-12 22:10:10.000000', NULL, 1),
(540424, 53353, 14496, '<td valign="top">I have to say hat''s off just for making a card house bigger than I ever can!</td>', 'I have to say hat''s off just for making a card house bigger than I ever can!', '2004-01-12 22:10:35.000000', NULL, 1),
(540425, 53874, 14836, '<td valign="top">Very nice. Thank god for photoshop!</td>', 'Very nice. Thank god for photoshop!', '2004-01-12 22:10:59.000000', NULL, 1),
