(541678, 53459, 11078, '<td valign="top">You certainly deserve the ribbon after that effort<br/>very unusual shot</td>', 'You certainly deserve the ribbon after that effortvery unusual shot', '2004-01-14 00:29:48.000000', NULL, 0),
(541679, 54104, 13136, '<td valign="top">I am surprised at how low you finished. I really thought this would be in the top 10. Good work on this shot.</td>', 'I am surprised at how low you finished. I really thought this would be in the top 10. Good work on this shot.', '2004-01-14 00:30:21.000000', NULL, 0),
